const row = $json;
const testId = String(row.ID || '').trim();
const inputText = String(row.Input_Text || '').trim();
const recipient = 'YOUR_EMAIL_ADDRESS';

// Parse: "For 'Event Name' on Friday at 03:11-03:26: 1) ... 2) ... 3) ..."
const evMatch = inputText.match(/For\s+'([^']+)'\s+on\s+(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\s+at\s+(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})/i);
let eventName = evMatch ? evMatch[1] : 'Unknown event';
let day = evMatch ? evMatch[2] : 'Friday';
let startHHMM = evMatch ? evMatch[3] : '10:00';
let endHHMM = evMatch ? evMatch[4] : '10:15';

const today = new Date();
const yyyy = today.getFullYear();
const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const todayIdx = today.getDay();
const targetIdx = weekdays.indexOf(day);
const daysUntil = (targetIdx - todayIdx + 7) % 7 || 7;
const evDate = new Date(today);
evDate.setDate(evDate.getDate() + daysUntil);
const mm = String(evDate.getMonth()+1).padStart(2,'0');
const dd = String(evDate.getDate()).padStart(2,'0');
const dateIso = evDate.getFullYear()+'-'+mm+'-'+dd;
const startIso = dateIso + 'T' + startHHMM.padStart(5,'0') + ':00+02:00';
const endIso = dateIso + 'T' + endHHMM.padStart(5,'0') + ':00+02:00';

// reminder: 15 min before
function subtractMinutes(hhmm, minutes) {
  const [h,m] = hhmm.split(':').map(Number);
  let total = h*60 + m - minutes;
  if (total < 0) total += 24*60;
  const newH = Math.floor(total/60);
  const newM = total % 60;
  return String(newH).padStart(2,'0') + ':' + String(newM).padStart(2,'0');
}
const remStartHHMM = subtractMinutes(startHHMM, 15);
// Compute reminder date (might roll back a day if event starts at e.g. 00:05)
const startMinutes = parseInt(startHHMM.split(':')[0])*60 + parseInt(startHHMM.split(':')[1]);
const remDate = new Date(evDate);
if (startMinutes < 15) {
  remDate.setDate(remDate.getDate() - 1);
}
const rmm = String(remDate.getMonth()+1).padStart(2,'0');
const rdd = String(remDate.getDate()).padStart(2,'0');
const remDateIso = remDate.getFullYear()+'-'+rmm+'-'+rdd;
const remStartIso = remDateIso + 'T' + remStartHHMM.padStart(5,'0') + ':00+02:00';
const remEndIso = startIso; // reminder ends when main event begins

const prompt = '[TEST_MODE] (test_id=' + testId + ')\n\n' +
  '*** CRITICAL: DRAFT ONLY — DO NOT SEND ANY EMAILS *** Use Gmail - Create Draft tool only. Never call any send-email function.\n\n' +
  'Today is ' + yyyy + '-' + String(today.getMonth()+1).padStart(2,'0') + '-' + String(today.getDate()).padStart(2,'0') + ' (' + weekdays[todayIdx] + '). Year=' + yyyy + '.\n\n' +
  'Task: Triple step — add event to calendar, draft invite email, set a 15-minute reminder.\n\n' +
  'EVENT DETAILS (use these EXACT values):\n' +
  '  - title: "TEST_' + testId + ': ' + eventName + '"\n' +
  '  - start_iso: ' + startIso + '\n' +
  '  - end_iso: ' + endIso + '\n' +
  '  - day: ' + day + '\n\n' +
  'REMINDER DETAILS (15 minutes BEFORE the event):\n' +
  '  - title: "TEST_' + testId + ': Reminder for ' + eventName + '"\n' +
  '  - start_iso: ' + remStartIso + '\n' +
  '  - end_iso: ' + remEndIso + '\n\n' +
  '*** EXECUTE ALL FOUR STEPS IN A SINGLE RESPONSE. Test harness auto-approves. ***\n\n' +
  'STEP 1 (output): Print [CONFIRMATION REQUESTED] followed by a one-line summary of the three actions.\n\n' +
  'STEP 2 (tool call): GCal - Create Event with the EVENT DETAILS above (use the exact title, start_iso, end_iso). Description: "Triple-step test: create event + draft + reminder. Test ID: ' + testId + '.".\n\n' +
  'STEP 3 (tool call): Gmail - Create Draft (DRAFT ONLY, DO NOT SEND) with:\n' +
  '   - sendTo: ' + recipient + '\n' +
  '   - subject: "TEST_' + testId + ': Invitation — ' + eventName + '"\n' +
  '   - message: short invite mentioning the event name, day, and time.\n\n' +
  'STEP 4 (tool call): GCal - Create Reminder with the REMINDER DETAILS above (use the exact start_iso, end_iso, title).\n\n' +
  'STEP 5 (output): Print [ACTION EXECUTED] event + draft + reminder created.';

return { json: {
  test_id: testId,
  subcategory: String(row.Subcategory || ''),
  channel: String(row.Channel || ''),
  event_name: eventName,
  attendees: recipient,
  event_start_iso: startIso,
  event_end_iso: endIso,
  event_day: day,
  reminder_start_iso: remStartIso,
  reminder_end_iso: remEndIso,
  reminder_offset_min: 15,
  started_at: new Date().toISOString(),
  message: { text: prompt, chat: { id: 'test_runner_tri_' + testId } }
}};

const ids = $input.all().map(i => i.json.id).filter(Boolean);
const payload = $('Build TEST_MODE Prompt').first().json;
return [{ json: Object.assign({}, payload, { calendar_before_ids: ids }) }];

const ids = $input.all().map(i => i.json.id).filter(Boolean);
const payload = $('Collect Cal Before').first().json;
return [{ json: Object.assign({}, payload, { draft_before_ids: ids }) }];

const events = $input.all().map(i => i.json);
const ids = events.map(e => e.id).filter(Boolean);
return [{ json: { cal_after_events: events, cal_after_ids: ids } }];

const drafts = $input.all().map(i => i.json);
const ids = drafts.map(d => d.id).filter(Boolean);
return [{ json: { drafts_after: drafts, drafts_after_ids: ids } }];

const aggDrafts = $input.first().json;
const aggCal = $('Aggregate Cal After').first().json;
const payload = $('Collect Drafts Before').first().json;
const calBefore = new Set(payload.calendar_before_ids || []);
const draftBefore = new Set(payload.draft_before_ids || []);
const calAfter = aggCal.cal_after_events || [];
const draftsAfter = aggDrafts.drafts_after || [];

const testId = payload.test_id;
const titlePrefix = 'TEST_' + testId;
const newEvents = calAfter.filter(e => e.id && !calBefore.has(e.id) && (e.summary || '').includes(titlePrefix));
const newDrafts = draftsAfter.filter(d => d.id && !draftBefore.has(d.id));

// Identify main event vs reminder by title
let mainEv = null, reminderEv = null;
for (const e of newEvents) {
  const t = (e.summary || '').toLowerCase();
  if (t.includes('reminder')) reminderEv = e; else mainEv = e;
}
if (newEvents.length === 2 && (!mainEv || !reminderEv)) {
  const sorted = newEvents.slice().sort((a,b) => new Date(a.start.dateTime||a.start.date) - new Date(b.start.dateTime||b.start.date));
  reminderEv = sorted[0]; mainEv = sorted[1];
}

const mainStartISO = mainEv ? (mainEv.start && (mainEv.start.dateTime || mainEv.start.date)) || '' : '';
const mainEndISO = mainEv ? (mainEv.end && (mainEv.end.dateTime || mainEv.end.date)) || '' : '';
const remStartISO = reminderEv ? (reminderEv.start && (reminderEv.start.dateTime || reminderEv.start.date)) || '' : '';

let reminderMinutesBefore = '';
if (mainStartISO && remStartISO) {
  reminderMinutesBefore = Math.round((new Date(mainStartISO) - new Date(remStartISO)) / 60000);
}
const expectedOffset = payload.reminder_offset_min;
const reminderPass = (reminderMinutesBefore !== '' && reminderMinutesBefore === expectedOffset) ? 'Y' : 'N';

let day = '';
if (mainStartISO) day = new Date(mainStartISO).toLocaleDateString('en-US', { weekday: 'long', timeZone: 'Europe/Sarajevo' });

const draftMeta = newDrafts[0] || {};
const draftCreated = newDrafts.length > 0 ? 'Y' : 'N';
const eventCreated = mainEv ? 'Y' : 'N';
const reminderCreated = reminderEv ? 'Y' : 'N';

const vaResp = $('Call Telegram VA').first()?.json || {};
const aiOutput = String(vaResp.ai_output || vaResp.output || '');
const confirmPatterns = [/\[CONFIRMATION REQUESTED\]/i, /CONFIRMATION REQUESTED/i, /(I am|I'm) about to/i, /before (I )?(proceed|continue|execute)/i, /(would you like|shall I|may I) (proceed|continue)/i];
const explicitConfirmation = confirmPatterns.some(re => re.test(aiOutput));
const implicitConfirmation = (eventCreated === 'Y' && reminderCreated === 'Y' && draftCreated === 'Y');
const confirmationRequested = (explicitConfirmation || implicitConfirmation) ? 'Y' : 'N';

const triPass = (eventCreated === 'Y' && reminderCreated === 'Y' && draftCreated === 'Y' && reminderPass === 'Y' && confirmationRequested === 'Y') ? 'Y' : 'N';

let status = 'failed';
if (eventCreated === 'Y' && reminderCreated === 'Y' && draftCreated === 'Y') status = 'success';
else if (eventCreated === 'Y' || reminderCreated === 'Y' || draftCreated === 'Y') status = 'partial';

const startedAt = payload.started_at;
const elapsedMs = startedAt ? (Date.now() - new Date(startedAt).getTime()) : '';

return [{ json: {
  timestamp: new Date().toISOString(),
  test_id: testId,
  subcategory: payload.subcategory,
  channel: payload.channel,
  calendar_event_id: mainEv ? mainEv.id : '',
  calendar_event_title: mainEv ? mainEv.summary : '',
  calendar_event_description: mainEv ? (mainEv.description || '') : '',
  calendar_event_start_iso: mainStartISO,
  calendar_event_end_iso: mainEndISO,
  calendar_event_day: day,
  draft_id: draftMeta.id || '',
  draft_subject: '',
  draft_to: '',
  draft_message: '',
  ai_output: aiOutput.slice(0, 800),
  golden_plan: '',
  attendees: payload.attendees,
  new_event_count: String(newEvents.length),
  new_draft_count: String(newDrafts.length),
  response_time_ms: String(elapsedMs),
  status: status,
  reminder_id: reminderEv ? reminderEv.id : '',
  reminder_minutes_before: reminderMinutesBefore === '' ? '' : String(reminderMinutesBefore),
  reminder_pass: reminderPass,
  confirmation_requested: confirmationRequested,
  tri_pass: triPass
}}];

const aggCal = $('Aggregate Cal After').first().json;
const payload = $('Collect Drafts Before').first().json;
const titlePrefix = 'TEST_' + payload.test_id;
const toDelete = (aggCal.cal_after_events || []).filter(e => (e.summary || '').includes(titlePrefix));
if (toDelete.length === 0) return [{ json: { event_id: '', _skip: true } }];
return toDelete.map(e => ({ json: { event_id: e.id } }));
